files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #f5a623;
  --lamp-off: #555;
  --lamp-on: #ffd966;
  --switch-bg: #444;
  --switch-on: #4caf50;
  --focus: #ffcc00;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 28px;
  margin-bottom: 16px;
  text-align: center;
  color: var(--accent);
}

.counter {
  text-align: center;
  font-size: 20px;
  margin-bottom: 24px;
  font-weight: 600;
}

.switchboard {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

.switch-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px;
  background: rgba(255,255,255,0.05);
  border-radius: 8px;
}

.switch-label {
  font-size: 16px;
  min-width: 24px;
  font-weight: 600;
}

.lamp {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--lamp-off);
  border: 2px solid #333;
  transition: background 0.2s, box-shadow 0.2s;
  flex-shrink: 0;
}

.lamp.on {
  background: var(--lamp-on);
  box-shadow: 0 0 12px var(--lamp-on);
}

button {
  font-family: inherit;
  font-size: 16px;
  cursor: pointer;
}

.switch-btn {
  background: var(--switch-bg);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 8px 12px;
  min-width: 60px;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  font-weight: 600;
}

.switch-btn:hover {
  background: #5a5a6a;
}

.switch-btn:active {
  transform: scale(0.95);
}

.switch-btn.on {
  background: var(--switch-on);
  border-color: #2e7d32;
}

.switch-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.btn {
  background: var(--accent);
  color: #1e1e2f;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-weight: 700;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background: #ffb84d;
}

.btn:active {
  transform: scale(0.95);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .switchboard {
    grid-template-columns: 1fr;
  }
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 24px;
  }
}

[hidden] {
  display: none !important;
}

const switchboard = document.getElementById('switchboard');
const counterEl = document.getElementById('counter');
const allOnBtn = document.getElementById('allOn');
const allOffBtn = document.getElementById('allOff');

const NUM_SWITCHES = 8;
const labels = ['A','B','C','D','E','F','G','H'];
const switches = [];

function createSwitch(label) {
  const item = document.createElement('div');
  item.className = 'switch-item';

  const labelEl = document.createElement('span');
  labelEl.className = 'switch-label';
  labelEl.textContent = label;

  const lamp = document.createElement('span');
  lamp.className = 'lamp';
  lamp.setAttribute('aria-hidden', 'true');

  const btn = document.createElement('button');
  btn.className = 'switch-btn';
  btn.textContent = 'Off';
  btn.setAttribute('aria-pressed', 'false');
  btn.setAttribute('aria-label', `Switch ${label}`);

  btn.addEventListener('click', () => {
    const on = btn.getAttribute('aria-pressed') === 'true';
    setSwitchState(btn, lamp, !on);
    updateCounter();
  });

  item.appendChild(labelEl);
  item.appendChild(lamp);
  item.appendChild(btn);
  return { item, btn, lamp };
}

function setSwitchState(btn, lamp, on) {
  btn.setAttribute('aria-pressed', String(on));
  btn.textContent = on ? 'On' : 'Off';
  btn.classList.toggle('on', on);
  lamp.classList.toggle('on', on);
}

function updateCounter() {
  const count = switches.filter(s => s.btn.getAttribute('aria-pressed') === 'true').length;
  counterEl.textContent = count;
}

function setAll(state) {
  switches.forEach(s => setSwitchState(s.btn, s.lamp, state));
  updateCounter();
}

for (let i = 0; i < NUM_SWITCHES; i++) {
  const sw = createSwitch(labels[i]);
  switchboard.appendChild(sw.item);
  switches.push(sw);
}

allOnBtn.addEventListener('click', () => setAll(true));
allOffBtn.addEventListener('click', () => setAll(false));

updateCounter();
